// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));

        amount = bound(amount, 0, 100 ether);

        vm.deal(sender, 100 ether);
        vm.prank(sender);

        uint256 before = address(c).balance;

        bool ok;
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        if (amount == 10 ether) {
            uint256 afterBal = address(c).balance;
            uint256 pastTime = c.pastBlockTime();

            bool expectedBalanceOk;
            if (block.number % 15 == 0) {
                expectedBalanceOk = (afterBal == 0);
            } else {
                expectedBalanceOk = (afterBal == before + 10 ether);
            }

            assertTrue(ok && pastTime == block.timestamp && expectedBalanceOk);
        } else {
        }
    }
}
